using System;
using System.Collections.Generic;
using System.Data;
using System.Web;
using System.Web.UI;

using Sunplus.Agent.Model.BL.TotalBets;
using Sunplus.Agent.Model.BL.Definitions;

using Fanex.Age.UI;

using Fanex.Age.UI.Components;


