namespace Fanex.Age.UI.TotalBets
{

    public partial class Financial_Page : TotalBets_Page
    {
        #region Const
        const int M5 = 0;
        const int M15 = 1;
        const int M30 = 2;
        const int M45 = 3;
        const int M60 = 4;
        const int MD = 5;
        #endregion

        #region Override
        /// <summary>
        /// The data sample
        /// leagueid    matchid     homeid      bettype home_total            away_total            winlost
        /// ----------- ----------- ----------- ------- --------------------- --------------------- ---------------------
        /// 0           763595      500         51      0.00                  0.00                  0.00
        /// 0           763595      500         61      0.00                  0.00                  0.00
        /// 
        /// BetType 5x and 6x is render in the same block
        /// </summary>
        /// <param name="writer"></param>
        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable financial = View as DataTable;

            Financial_Template tpl = new Financial_Template();

            tpl.Contents.StockIndex.Clear();
            if (financial.Rows.Count > 0)
            {
                tpl.Contents.NotFoundContent.Hide();

                // Render league content
                int currentIndexId = 0;
                int betTypeIndex = 1;
                int[] markBetType = new int[6] { 0, 0, 0, 0, 0, 0 };

                Financial_Contents_StockIndex_Block stockBlock = new Financial_Contents_StockIndex_Block();
                Financial_Contents_StockIndex_BetType_Block[] betTypeBlocks = new Financial_Contents_StockIndex_BetType_Block[6];
                for (int j = 0; j < betTypeBlocks.Length; j++)
                {
                    betTypeBlocks[j] = new Financial_Contents_StockIndex_BetType_Block();
                }
                decimal OUTotal = 0, OETotal = 0, OUWinlossTotal = 0, OEWinlossTotal = 0;
                for (int i = 0; i < financial.Rows.Count; i++)
                {
                    DataRow dr = financial.Rows[i];

                    int indexId = Convert.ToInt32(dr["homeid"]);

                    // Start new stock index
                    if (i == 0 || currentIndexId != indexId)
                    {
                        stockBlock.BetType.Clear();
                        stockBlock.IndexName = indexId.ToString();
                        // Default value for each bettype
                        markBetType = new int[6] { 0, 0, 0, 0, 0, 0 };
                        for (int j = 0; j < betTypeBlocks.Length; j++)
                        {
                            betTypeBlocks[j].OEText.Show();
                            betTypeBlocks[j].OELink.Hide();
                            betTypeBlocks[j].OUText.Show();
                            betTypeBlocks[j].OULink.Hide();
                            betTypeBlocks[j].OULink.OUTurnOverValue = "0";
                            betTypeBlocks[j].OUText.OUTurnOverValue = "0";
                            betTypeBlocks[j].OUWinlossValue = "0";
                            betTypeBlocks[j].OELink.OETurnOverValue = "0";
                            betTypeBlocks[j].OEText.OETurnOverValue = "0";
                            betTypeBlocks[j].OEWinlossValue = "0";
                            betTypeBlocks[j].ColorOver = Fanex.Age.UI.Common.RowBgOver;
                            betTypeBlocks[j].OULink.BetTypeMatch = Fanex.Age.UI.Common.BetListByBetTypeMatch;
                            betTypeBlocks[j].OELink.BetTypeMatch = Fanex.Age.UI.Common.BetListByBetTypeMatch;
                        }
                    }

                    RenderStockBetTypeRow(betTypeBlocks, dr, markBetType, ref OUTotal, ref OUWinlossTotal, ref OETotal, ref OEWinlossTotal);

                    // End of stock index

                    if (i == financial.Rows.Count - 1 || indexId != Convert.ToInt32(financial.Rows[i + 1]["homeid"]))
                    {
                        int colorIndex = 0;
                        // Render total block
                        for (int j = 0; j < betTypeBlocks.Length; j++)
                        {
                            if (markBetType[j] != 0)
                            {
                                betTypeBlocks[j].ColorClass = (colorIndex % 2) == 0 ? Fanex.Age.UI.Common.RowBgEven : Fanex.Age.UI.Common.RowBgOdd;
                                betTypeBlocks[j].NoValue = betTypeIndex.ToString();
                                betTypeIndex++;
                                colorIndex++;
                                stockBlock.BetType.Append(betTypeBlocks[j]);
                            }
                        }
                        stockBlock.TotalContents.OETurnOverTotal = Formater.DecFormat(OETotal, 0);
                        stockBlock.TotalContents.OEWinlossTotal = Formater.DecFormat(OEWinlossTotal, 0);
                        stockBlock.TotalContents.OUTurnOverTotal = Formater.DecFormat(OUTotal, 0);
                        stockBlock.TotalContents.OUWinlossTotal = Formater.DecFormat(OUWinlossTotal, 0);

                        tpl.Contents.StockIndex.Append(stockBlock);
                        OETotal = OEWinlossTotal = OUTotal = OUWinlossTotal = 0;
                    }
                    currentIndexId = indexId;
                }
            }

            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }   
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetFinancial();
        }
        #endregion

        #region Utility

        /// <summary>
        /// Render stock bet type row
        /// </summary>
        /// <param name="betTypeBlock"></param>
        /// <param name="dr"></param>
        /// <param name="betIndex"></param>
        /// <param name="rowIndex"></param>
        /// <param name="OUTurnOverTotal"></param>
        /// <param name="OUWinlossTotal"></param>
        /// <param name="OETurnOverTotal"></param>
        /// <param name="OEWinlossTotal"></param>
        private void RenderStockBetTypeRow(Financial_Contents_StockIndex_BetType_Block[] betTypeBlocks, DataRow dr, int[] markBetType, ref decimal OUTurnOverTotal, ref decimal OUWinlossTotal, ref decimal OETurnOverTotal, ref decimal OEWinlossTotal)
        {
            int betType = Convert.ToInt32(dr["bettype"]);

            decimal turnOver = Decimal.Round((decimal)dr["home_total"], 0) - Decimal.Round((decimal)dr["away_total"], 0);

            if (betType >= 51 && betType <= 56)
            {
                OUTurnOverTotal += turnOver;
                OUWinlossTotal += Decimal.Round((decimal)dr["winlost"], 0);
            }
            else if (betType >= 61 && betType <= 66)
            {
                OETurnOverTotal += turnOver;
                OEWinlossTotal += Decimal.Round((decimal)dr["winlost"], 0);
            }

            int betTypeIndex = GetBetTypeIndex(betType);
            markBetType[betTypeIndex]++;
            bool isOU = IsOU(betType);

            if (isOU)
            {
                betTypeBlocks[betTypeIndex].OULink.OUTurnOverValue = NegativeNumberRoundColor(turnOver);
                betTypeBlocks[betTypeIndex].OULink.Show();
                betTypeBlocks[betTypeIndex].OUText.Hide();
                betTypeBlocks[betTypeIndex].OUWinlossValue = Formater.DecFormat(dr["winlost"], 0);
            }
            else
            {

                betTypeBlocks[betTypeIndex].OELink.OETurnOverValue = NegativeNumberRoundColor(turnOver);
                betTypeBlocks[betTypeIndex].OEWinlossValue = Formater.DecFormat(dr["winlost"], 0);
                betTypeBlocks[betTypeIndex].OELink.Show();
                betTypeBlocks[betTypeIndex].OEText.Hide();
            }
            // Bet time 
            String betTime = Sunplus.Agent.Model.BL.Cache.CacheRef.GetBettype(dr["bettype"]);
            if (!string.IsNullOrEmpty(betTime))
            {
                betTime = betTime.Substring(0, betTime.Length - 3);
            }
            betTypeBlocks[betTypeIndex].BetTime = betTime;


        }

        /// <summary>
        /// Return bet type index of mark bet type array
        /// 51->0, 52->1, 53->2, 54->3, 55->4, 56->5
        /// 61->0, 62->1, 63->2, 64->3, 65->4, 66->5
        /// </summary>
        /// <param name="betType"></param>
        /// <returns></returns>
        private int GetBetTypeIndex(int betType)
        {
            return (betType % 10) - 1;
        }

        /// <summary>
        /// BetType is OU if it is between 51 and 56
        /// </summary>
        /// <param name="betType"></param>
        /// <returns></returns>
        private bool IsOU(int betType)
        {
            return betType < 60 ? true : false;
        }

        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private static string NegativeNumberRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);

            return num < 0 ? "<font color='#eb6003'>" + Formater.DecFormat(num, 0) + "</font>" : Formater.DecFormat(num, 0);

        }
        #endregion
    }

}
